  const onChangeText = (text) => {
    setSectionName(text);
  };

  return (
    <Fragment>
      {!allowEdit ? (
        <Text preset="bold" text={item.name} />
      ) : (
        <SectionInput testID="textInput" onChangeText={onChangeText} mode="small" label="" name={`${fieldName}.name`} />
